begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('13900000-0000-0000-0000-000000000001','notify-owner@test.invalid','{}'),('13900000-0000-0000-0000-000000000002','notify-other@test.invalid','{}');
insert into public.profile_roles(profile_id,role_id) values('13900000-0000-0000-0000-000000000001','administrator'),('13900000-0000-0000-0000-000000000002','sales_manager');
set local request.jwt.claims='{"sub":"13900000-0000-0000-0000-000000000001","role":"authenticated"}';
create temp table notification_rfq as select (public.create_sales_desk_rfq(jsonb_build_object('customer_name','Notification target','media_platform_id',(select id from public.sales_desk_media_platforms limit 1)))->>'id')::uuid id;
grant select on notification_rfq to authenticated;
insert into public.user_notifications(id,user_id,channel,kind,title,target_page,target_record_id,dedupe_key) values
('13900000-0000-0000-0001-000000000001','13900000-0000-0000-0000-000000000001','system','test','Delete me',null,null,'delete-test'),
('13900000-0000-0000-0001-000000000002','13900000-0000-0000-0000-000000000002','system','test','Someone else',null,null,null);
insert into public.user_notifications(id,user_id,channel,kind,title,target_page,target_record_id) select '13900000-0000-0000-0001-000000000003','13900000-0000-0000-0000-000000000001','sales_desk','rfq_chat_update','RFQ Update','RFQs',id from notification_rfq;
set local role authenticated;
select is(public.delete_user_notification('13900000-0000-0000-0001-000000000002'),false,'cannot delete another recipient notification');
select is(public.delete_user_notification('13900000-0000-0000-0001-000000000001'),true,'owner can delete their notification');
select is(public.delete_user_notification('13900000-0000-0000-0001-000000000001'),true,'deletion is idempotent');
select is((select count(*) from public.user_notifications where id='13900000-0000-0000-0001-000000000001'),0::bigint,'deleted notification disappears from list');
select is((select unread_count from public.user_notification_unread_counts() where notification_channel='__all__'),1::bigint,'deleted unread notification no longer contributes to count');
select is(public.open_user_notification('13900000-0000-0000-0001-000000000001')->>'status','missing','deleted notification cannot be reopened');
select is(public.open_user_notification('13900000-0000-0000-0001-000000000002')->>'status','missing','opening another recipient notification leaks no details');
select is(public.open_user_notification('13900000-0000-0000-0001-000000000003')->>'status','ready','live RFQ notification opens');
select ok((select read_at is not null from public.user_notifications where id='13900000-0000-0000-0001-000000000003'),'opening marks notification read');
reset role;
update public.user_notifications set title='Retry of deleted event',read_at=null where dedupe_key='delete-test';
set local role authenticated;
select is((select count(*) from public.user_notifications where id='13900000-0000-0000-0001-000000000001'),0::bigint,'retrying an existing event cannot resurrect a deleted notification');
reset role;
select public.archive_sales_desk_rfq((select id from notification_rfq));
set local role authenticated;
select is(public.open_user_notification('13900000-0000-0000-0001-000000000003')->>'status','unavailable','stale notification recognizes soft-deleted RFQ');
select is((select count(*) from public.user_notifications where id='13900000-0000-0000-0001-000000000003'),0::bigint,'stale RFQ notification is removed from the list');
reset role;
insert into public.user_notifications(id,user_id,channel,kind,title,target_record_id) values('13900000-0000-0000-0001-000000000004','13900000-0000-0000-0000-000000000001','sales_desk','rfq_updated','Missing RFQ','13900000-0000-0000-0002-000000000099');
set local role authenticated;
select is(public.open_user_notification('13900000-0000-0000-0001-000000000004')->>'status','unavailable','physically missing RFQ is handled safely');
reset role;
-- A notification is not authority to read an RFQ after workspace access is revoked.
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values('13900000-0000-0000-0000-000000000002','sales_desk','sales_desk.view',false);
insert into public.user_notifications(id,user_id,channel,kind,title,target_record_id) select '13900000-0000-0000-0001-000000000005','13900000-0000-0000-0000-000000000002','sales_desk','rfq_updated','No longer accessible',id from notification_rfq;
update public.sales_desk_rfqs set deleted_at=null where id=(select id from notification_rfq);
set local role authenticated;
set local request.jwt.claims='{"sub":"13900000-0000-0000-0000-000000000002","role":"authenticated"}';
select is(public.open_user_notification('13900000-0000-0000-0001-000000000005')->>'status','unavailable','opening checks live RFQ permissions');
reset role;
select ok((select dismissed_at is null from public.user_notifications where id='13900000-0000-0000-0001-000000000002'),'other recipient notification remains intact');
update public.profiles set active=false where id='13900000-0000-0000-0000-000000000002';
set local role authenticated;
select is(public.delete_user_notification('13900000-0000-0000-0001-000000000002'),false,'inactive recipient cannot mutate notifications');
reset role;
select ok(not has_function_privilege('anon','public.delete_user_notification(uuid)','execute'),'signed out users cannot delete notifications');
select ok(not has_function_privilege('anon','public.open_user_notification(uuid)','execute'),'signed out users cannot resolve notifications');
select ok(not has_table_privilege('authenticated','public.user_notifications','update'),'browser cannot forge notification data');
select * from finish();
rollback;
